import fs from "node:fs";
import path from "node:path";
import { expect, test } from "@playwright/test";

/**
 * Every page in the sitemap: loads, has real pre-rendered content, is
 * indexable, throws no errors, and fits a phone screen without sideways
 * scrolling.
 */

// The sitemap is generated by the build, so new pages are tested automatically.
const sitemap = fs.readFileSync(path.join(process.cwd(), "dist", "sitemap.xml"), "utf8");
const pages = [...sitemap.matchAll(/<loc>https:\/\/juasoh\.com([^<]*)<\/loc>/g)].map((m) => m[1] || "/");

test("the sitemap lists the main pages", () => {
  for (const page of ["/", "/about", "/work", "/projects", "/experience", "/contact"]) {
    expect(pages).toContain(page);
  }
  expect(pages).not.toContain("/inbox");
});

for (const page of pages) {
  test(`${page} loads cleanly`, async ({ page: browser, request }) => {
    // The server sends real HTML (pre-rendered), not an empty shell.
    const raw = await request.get(page);
    expect(raw.status()).toBe(200);
    const html = await raw.text();
    expect(html).toMatch(/<h1[\s>]/);
    expect(html).toContain('content="index, follow');
    expect(html).toMatch(/<link rel="canonical" href="https:\/\/juasoh\.com/);

    const errors: string[] = [];
    browser.on("pageerror", (err) => errors.push(err.message));
    browser.on("console", (msg) => {
      if (msg.type() === "error") errors.push(msg.text());
    });

    await browser.goto(page);
    await expect(browser.locator("h1").first()).toBeVisible();
    await expect(browser).toHaveTitle(/Joshua Asoh/);

    // No sideways scrolling, on desktop or phone.
    const overflow = await browser.evaluate(
      () => document.documentElement.scrollWidth - document.documentElement.clientWidth
    );
    expect(overflow).toBeLessThanOrEqual(1);

    expect(errors).toEqual([]);
  });
}

test("unknown pages show the 404 page", async ({ page }) => {
  await page.goto("/this-page-does-not-exist");
  await expect(page.getByRole("heading", { name: "Page not found" })).toBeVisible();
});

test("analytics stays off outside juasoh.com", async ({ page }) => {
  const analytics: string[] = [];
  page.on("request", (req) => {
    if (/googletagmanager|google-analytics/.test(req.url())) analytics.push(req.url());
  });
  await page.goto("/");
  await page.waitForLoadState("networkidle");
  expect(analytics).toEqual([]);
});

test("the private admin page is hidden from search", async ({ page, request }) => {
  const html = await (await request.get("/inbox")).text();
  expect(html).toContain('<meta name="robots" content="noindex"');
  expect(html).not.toContain('rel="canonical"');

  const robots = await (await request.get("/robots.txt")).text();
  expect(robots).toContain("Disallow: /inbox");

  await page.goto("/inbox");
  await expect(page.getByRole("button", { name: "Sign in" })).toBeVisible();
});
